// AgentRegistryServer is the server API for AgentRegistry service.
// All implementations must embed UnimplementedAgentRegistryServer
// for forward compatibility.
//
// Service for managing Agent Registry resources.
type AgentRegistryServer interface {
	// Lists Agents in a given project and location.
	ListAgents(context.Context, *ListAgentsRequest) (*ListAgentsResponse, error)
	// Searches Agents in a given project and location.
	SearchAgents(context.Context, *SearchAgentsRequest) (*SearchAgentsResponse, error)
	// Gets details of a single Agent.
	GetAgent(context.Context, *GetAgentRequest) (*Agent, error)
	// Lists Endpoints in a given project and location.
	ListEndpoints(context.Context, *ListEndpointsRequest) (*ListEndpointsResponse, error)
	// Gets details of a single Endpoint.
	GetEndpoint(context.Context, *GetEndpointRequest) (*Endpoint, error)
	// Lists McpServers in a given project and location.
	ListMcpServers(context.Context, *ListMcpServersRequest) (*ListMcpServersResponse, error)
	// Searches McpServers in a given project and location.
	SearchMcpServers(context.Context, *SearchMcpServersRequest) (*SearchMcpServersResponse, error)
	// Gets details of a single McpServer.
	GetMcpServer(context.Context, *GetMcpServerRequest) (*McpServer, error)
	// Lists Services in a given project and location.
	ListServices(context.Context, *ListServicesRequest) (*ListServicesResponse, error)
	// Gets details of a single Service.
	GetService(context.Context, *GetServiceRequest) (*Service, error)
	// Creates a new Service in a given project and location.
	CreateService(context.Context, *CreateServiceRequest) (*longrunning.Operation, error)
	// Updates the parameters of a single Service.
	UpdateService(context.Context, *UpdateServiceRequest) (*longrunning.Operation, error)
	// Deletes a single Service.
	DeleteService(context.Context, *DeleteServiceRequest) (*longrunning.Operation, error)
	// Lists Bindings in a given project and location.
	ListBindings(context.Context, *ListBindingsRequest) (*ListBindingsResponse, error)
	// Gets details of a single Binding.
	GetBinding(context.Context, *GetBindingRequest) (*Binding, error)
	// Creates a new Binding in a given project and location.
	CreateBinding(context.Context, *CreateBindingRequest) (*longrunning.Operation, error)
	// Updates the parameters of a single Binding.
	UpdateBinding(context.Context, *UpdateBindingRequest) (*longrunning.Operation, error)
	// Deletes a single Binding.
	DeleteBinding(context.Context, *DeleteBindingRequest) (*longrunning.Operation, error)
	// Fetches available Bindings.
	FetchAvailableBindings(context.Context, *FetchAvailableBindingsRequest) (*FetchAvailableBindingsResponse, error)
	// =========================================================================
	// # Skills Collection APIs
	//
	// Creates a Skill resource container, optionally publishing the initial
	// SkillRevision inline in a single, atomic CRUD roundtrip.
	CreateSkill(context.Context, *CreateSkillRequest) (*longrunning.Operation, error)
	// Fetches the active configuration and metadata of a Skill.
	GetSkill(context.Context, *GetSkillRequest) (*Skill, error)
	// Updates Skill metadata or overrides active pointers/state using REST
	// standard PATCH.
	UpdateSkill(context.Context, *UpdateSkillRequest) (*longrunning.Operation, error)
	// Deletes a Skill container along with all its revisions.
	DeleteSkill(context.Context, *DeleteSkillRequest) (*longrunning.Operation, error)
	// Lists logical Skills available in a project.
	ListSkills(context.Context, *ListSkillsRequest) (*ListSkillsResponse, error)
	// Custom deep-search method to filter by frontmatter or query SKILL.md text
	// blobs.
	SearchSkills(context.Context, *SearchSkillsRequest) (*SearchSkillsResponse, error)
	// Creates a new immutable revision and triggers validation pipelines.
	CreateSkillRevision(context.Context, *CreateSkillRevisionRequest) (*longrunning.Operation, error)
	// Gets details of a single immutable Revision.
	GetSkillRevision(context.Context, *GetSkillRevisionRequest) (*SkillRevision, error)
	// Deletes a specific revision (restricted to admins to purge accidentally
	// committed secrets).
	DeleteSkillRevision(context.Context, *DeleteSkillRevisionRequest) (*longrunning.Operation, error)
	// Lists all revisions belonging to a parent Skill.
	ListSkillRevisions(context.Context, *ListSkillRevisionsRequest) (*ListSkillRevisionsResponse, error)
	// Fetches details of a specific Publisher.
	GetPublisher(context.Context, *GetPublisherRequest) (*Publisher, error)
	// Lists all Publishers in a location.
	ListPublishers(context.Context, *ListPublishersRequest) (*ListPublishersResponse, error)
	// Gets details of a single AI Application.
	GetAiApplication(context.Context, *GetAiApplicationRequest) (*AiApplication, error)
	// Lists AI Applications in a given project and location.
	ListAiApplications(context.Context, *ListAiApplicationsRequest) (*ListAiApplicationsResponse, error)
	// Gets details of a single Agent under an AI Application.
	GetAiApplicationAgent(context.Context, *GetAiApplicationAgentRequest) (*Agent, error)
	// Lists Agents under an AI Application.
	ListAiApplicationAgents(context.Context, *ListAiApplicationAgentsRequest) (*ListAiApplicationAgentsResponse, error)
	// Gets details of a single McpServer under an AI Application.
	GetAiApplicationMcpServer(context.Context, *GetAiApplicationMcpServerRequest) (*McpServer, error)
	// Lists McpServers under an AI Application.
	ListAiApplicationMcpServers(context.Context, *ListAiApplicationMcpServersRequest) (*ListAiApplicationMcpServersResponse, error)
	// Gets details of a single Finding.
	GetFinding(context.Context, *GetFindingRequest) (*Finding, error)
	// Lists Findings in a given project and location.
	ListFindings(context.Context, *ListFindingsRequest) (*ListFindingsResponse, error)
	// Gets details of a single Endpoint under an AI Application.
	GetAiApplicationEndpoint(context.Context, *GetAiApplicationEndpointRequest) (*Endpoint, error)
	// Lists Endpoints under an AI Application.
	ListAiApplicationEndpoints(context.Context, *ListAiApplicationEndpointsRequest) (*ListAiApplicationEndpointsResponse, error)
	// =========================================================================
	// # Skill Encryption Spec Service Methods
	//
	// Gets the customer-managed encryption key (CMEK) configuration for Skills in
	// a specific project and location.
	GetSkillEncryptionSpec(context.Context, *GetSkillEncryptionSpecRequest) (*SkillEncryptionSpec, error)
	// Updates the customer-managed encryption key (CMEK) configuration for Skills
	// in a specific project and location.
	//
	// This method is only allowed when no Skills exist in the target project and
	// location. If any Skill already exists in the location, the request fails
	// with `FAILED_PRECONDITION`.
	UpdateSkillEncryptionSpec(context.Context, *UpdateSkillEncryptionSpecRequest) (*longrunning.Operation, error)
	mustEmbedUnimplementedAgentRegistryServer()
}

